package com.theseusoft.service;
import com.theseusoft.dto.*; import com.theseusoft.repository.UserRepository; import com.theseusoft.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;} public AuthResponse login(LoginRequest request){var user=users.findByUsername(request.username()).filter(u->encoder.matches(request.password(),u.getPassword())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciales inválidas"));var roles=user.getRoles().stream().map(Enum::name).collect(java.util.stream.Collectors.toSet());return new AuthResponse(jwt.generate(user.getUsername(),roles),user.getUsername(),roles);} }
